import json,copy,re,hashlib,sys
from pathlib import Path
P=Path(__file__).parent;L=Path('legal-rewrite').resolve();sys.path.insert(0,str(L))
from substantive_impact import plain
S=json.loads((P/'source.json').read_text());by={x['number']:x for x in S}
H=lambda x:hashlib.sha256((x or '').encode()).hexdigest()
T="Les dispositions du présent article supprimant une imposition s'appliquent aux conventions conclues et aux actes passés à compter de l'entrée en vigueur de la loi portant cette suppression lorsqu'ils sont obligatoirement déclarés ou soumis à la formalité de l'enregistrement et, dans les autres cas, à leur présentation volontaire à la formalité à compter de cette date. Les faits générateurs antérieurs demeurent régis par les dispositions qui leur étaient applicables, notamment pour les tarifs, exonérations, réductions, franchises, liquidations, créances, paiements, contrôles, restitutions, prescriptions et recours. Aucun remboursement général des sommes antérieurement dues n'est institué."
CSI="Pour les réquisitions ou demandes présentées à compter de l'entrée en vigueur de la loi portant la suppression de la contribution de sécurité immobilière, aucune contribution n'est due, y compris lorsque l'acte, le droit ou l'inscription auquel se rapporte la demande est antérieur. Les réquisitions et demandes présentées antérieurement restent régies par les règles qui leur étaient applicables, notamment pour les réductions, exonérations, liquidations, créances, avances, imputations, restitutions, contrôles, prescriptions et recours. Aucun remboursement général des contributions antérieurement dues n'est institué."
AUT="La suppression de cette imposition n'emporte ni dispense des formalités civiles, de la publicité foncière ou de l'enregistrement demeurant nécessaires, ni modification de leur rang, de leurs effets ou de l'opposabilité des droits. Elle n'institue aucun prélèvement de remplacement. Les autres impositions non supprimées par le présent article, ainsi que les rémunérations et émoluments distincts légalement dus, conservent leur régime et leurs exonérations. La seule suppression du droit fixe ne peut faire basculer un acte qui relevait de ce droit vers une imposition proportionnelle ou progressive."
def paras(*xs):return '\n'.join('<p>'+x+'</p>'for x in xs)
D={};R={};N={};IM={};META={};B={}
def put(n,body,reason,note,measure,kind,before,after,quote,proposed_quote,benefit,classification='material_reduction',meta=None):
 D[n]=body;R[n]=reason;N[n]=note;IM[n]=(classification,measure,kind,before,after,quote,proposed_quote);B[n]=benefit
 if meta:META[n]=meta
put('674',paras('Le présent article est abrogé pour les faits générateurs auxquels la suppression du minimum de perception est applicable. Aucun minimum de 25 € ne relève le montant résultant de l’application des droits proportionnels ou progressifs concernés. Les exonérations, franchises et règles d’arrondi plus favorables demeurent applicables.',T,'Cette abrogation ne modifie ni les taux ni les assiettes des droits proportionnels ou progressifs, ni les règles d’arrondi de l’article 675. Aucun minimum de remplacement n’est institué.'),
 'Supprime le minimum général de perception de25€ sans modifier les taux proportionnels, progressifs ou les arrondis.',
 'Note2004-1485 art95IV entière lue : transition distinguant fait générateur obligatoire et présentation volontaire. Les25€ sont un plancher de perception, pas un droit fixe autonome et pas une baisse uniforme de25€ par acte. Article675 capturé et lu intégralement avant gel : arrondi à l’euro le plus proche,0,50pour1, inchangé.',
 'enregistrement-minimum-perception-suppression','tax_reduced','Le droit ou la taxe calculé en dessous de25€ est relevé à25€.','Le montant effectivement calculé reste dû sans relèvement au minimum25€ ; taux, assiette et arrondi inchangés.','Il ne peut être perçu moins de 25 €','Aucun minimum de 25 € ne relève le montant résultant de l’application des droits proportionnels ou progressifs concernés.',
 'Les exonérations, franchises et règles plus favorables sont expressément conservées. La suppression d’un plancher ne transforme pas une opération exonérée en opération taxable et n’ajoute aucun tarif ; les remboursements et avantages des anciens faits générateurs restent ouverts.',meta={'change_type':'full_repeal','repeal_policy_id':'editorial_direction_2026_10_19','repeal_scope':'Suppression prospective du seul minimum général de perception de25euros applicable aux droits proportionnels ou progressifs, sans supprimer ces droits.'})
# Droits fixes : chaque champ favorable est conservé ; pas de suppression des droits proportionnels distincts.
fam='droits-fixes-actes-cibles-suppression'
x=by['679']['source_xml'];body=x.replace('Sont soumis à une imposition fixe :','Ne donnent lieu à aucune imposition fixe au titre du présent article :')
put('679',body+paras('Les actes relevant des 1° à 4° ne peuvent être soumis à une imposition proportionnelle ou progressive du seul fait de la suppression de cette imposition fixe. Les qualifications et conditions qui les excluaient de ces impositions demeurent applicables.',T,AUT), 'Retire l’imposition fixe attachée aux quatre catégories de cet article, sans étendre les impositions proportionnelles.', 'Les1°à4° sont conservés : actes hors6771°–4°, hypothèques non proportionnelles, actes exemptés volontairement enregistrés et publications facultatives du décret55-22art37. Les fonctions civiles de ces actes ne sont pas supprimées. Les taux fixes d’autres articles non visés ne sont pas réputés tous abolis.',fam,'tax_removed','Quatre catégories d’actes donnent ouverture à une imposition fixe.','Ces quatre catégories ne donnent plus ouverture à cette imposition fixe ; les qualifications et formalités civiles restent.','Sont soumis à une imposition fixe','Ne donnent lieu à aucune imposition fixe au titre du présent article', 'La gratuité future renforce les exemptions des actes présentés volontairement. Les exclusions du proportionnel demeurent, sans basculement vers un autre droit du seul fait du retrait du fixe ; les droits anciens conservent tous leurs avantages.')
put('680',paras('Les actes qui ne se trouvent ni exonérés ni tarifés par aucun autre article du présent code et qui ne peuvent donner lieu à une imposition proportionnelle ou progressive ne sont soumis à aucune imposition fixe au titre du présent article. La suppression de l’imposition de 125 € ne les soumet pas, par elle-même, à une autre imposition.',"Les transactions mentionnées au 9° du 1 de l'article 635, qui ne sont tarifées par aucun autre article du présent code, demeurent exonérées de cette imposition fixe. Aucun enregistrement ou contrôle distinct prévu pour ces transactions n'est supprimé par cette exonération.",T,AUT), 'Supprime le droit fixe résiduel de125€ des actes innomés ; maintient l’exemption expresse des transactions contre désistement.', 'Article635 entier lu : 1,9° vise la transaction de désistement du recours contre un permis. La dispense de taxe ne supprime pas cet enregistrement. Les actes expressément tarifés ailleurs, notamment donations, mutations onéreuses ou fiducies, ne sont pas tous réputés couverts par cet article résiduel.',fam,'tax_removed','Actes non exonérés, non tarifés ailleurs et non proportionnels :125€.','Même champ sans droit fixe de125€ ; aucun élargissement au proportionnel et transaction6351,9° toujours exonérée.','sont soumis à une imposition fixe de 125 €','ne sont soumis à aucune imposition fixe au titre du présent article.', 'L’exemption existante du second alinéa est expressément conservée. Aucun avantage d’un autre article n’est supprimé ; les actes qui n’entraient pas dans le résiduel restent dans leur régime propre. Les anciens droits, exonérations et restitutions ne sont pas remis en cause.')
x=by['686']['source_xml'];body=x.replace('sont assujetties à une imposition fixe de 125 €','sont exonérées de l’imposition fixe de 125 €')
put('686',body+paras('Lorsque les conditions du premier alinéa sont réunies, la déclaration ou élection de command ne peut être soumise au tarif proportionnel ou progressif du seul fait de la suppression de l’imposition fixe. Le deuxième alinéa conserve son champ propre lorsque ces conditions ne sont pas réunies.',T,AUT), 'Supprime les125€ des élections de command recevables au régime fixe, sans supprimer les conditions qui les distinguent d’une seconde mutation.', 'Les conditions de faculté réservée, acte public et notification dans24heures restent identiques. Le deuxième alinéa et les taux ordinaires applicables si ces conditions ne sont pas remplies restent entiers : aucune nouvelle dispense proportionnelle générale. Une référence procédurale ancienne n’est pas présentée comme une réforme civile.',fam,'tax_removed','125€ si faculté réservée, acte public et notification24h ; sinon droit ordinaire.','Même champ conditionnel exonéré du fixe ; seconde mutation ou déclaration hors conditions conserve son régime.','sont assujetties à une imposition fixe de 125 €','sont exonérées de l’imposition fixe de 125 €', 'Le traitement favorable de la déclaration rapide et réservée est élargi par le retrait du seul125€. La garantie contre requalification automatique n’est pas perdue ; aucune augmentation des droits applicables aux autres faits distincts et aucune remise en cause des régimes anciens.')
put('687',paras('Le présent article est abrogé pour les faits générateurs auxquels la suppression du droit fixe est applicable. Les déclarations d’adjudicataires visées par le présent article ne donnent plus lieu à la taxe fixe de publicité foncière de 25 €, lorsque leur publicité est requise séparément de celle des actes passibles de l’imposition proportionnelle.',T,AUT), 'Supprime le droit fixe25€ des déclarations d’adjudicataires publiées séparément.', 'Le champ fiscal de la source demeure la déclaration d’adjudicataire et sa publicité séparée ; ni adjudication, ni droit proportionnel de la vente, ni condition civile d’acquisition ne sont abolis. Le renvoi source à l’ancienCPC707 reste une concordance historique à contrôler hors corpus, sans le recréer.',fam,'tax_removed','Taxe fixe de25€ lorsque déclaration publiée séparément de l’acte proportionnel.','Aucune taxe fixe25€ pour cette déclaration ; la vente et sa publicité restent distinctes.','une taxe fixe de publicité foncière de 25 €','ne donnent plus lieu à la taxe fixe de publicité foncière de 25 €', 'La dispense existante lorsque les publicités étaient conjointes n’est pas réduite. La publicité séparée devient également dispensée du fixe ; aucun prélèvement ne remplace cette taxe, et les droits et restitutions pour périodes anciennes restent conservés.',meta={'change_type':'full_repeal','repeal_policy_id':'editorial_direction_2026_10_19','repeal_scope':'Suppression prospective de la taxe fixe de publicité foncière de25euros frappant les déclarations d’adjudicataires publiées séparément.'})
put('691 bis',paras("Les actes d'acquisitions visées au A de l'article 1594-0 G sont exonérés de la taxe de publicité foncière ou du droit d'enregistrement de 125 € prévu par le présent article.",T,"Les conditions, substitutions d’engagements, prolongations et exonérations proportionnelles prévues à l’article 1594-0 G restent applicables. La suppression du droit fixe n’entraîne ni suppression de ces avantages ni perception d’un autre droit du seul fait de cette suppression.",AUT), 'Supprime les125€ résiduels des acquisitions bénéficiant du régime de construction1594-0G A.', '1594-0G entier lu : A IàVII, délai4ans, preuves, reprise des engagements, substitution1115, surfaces2500m²/collectifs/3quarts, prolongations annuelles, acceptation tacite2mois et clôture du remembrement restent. Le B n’est pas étendu ni réécrit. Le retrait du fixe ne dispense pas des conditions autonomes de l’exonération proportionnelle.',fam,'tax_removed','Acquisitions éligibles1594-0G A : droit ou taxe fixe125€ malgré exemption proportionnelle.','Ces acquisitions gardent leur exonération proportionnelle et ne supportent plus les125€ résiduels.','un droit d’enregistrement de 125 €'.replace('’',"'"),"sont exonérés de la taxe de publicité foncière ou du droit d'enregistrement de 125 €", 'L’exonération favorable, les changements d’engagement et les prolongations du1594-0G sont expressément maintenus pour les bénéficiaires futurs. Le retrait des125€ n’allonge ni ne raccourcit un délai, n’ajoute pas d’agrément, et ne déclenche aucune hausse des droits proportionnels.')
x=by['846 bis']['source_xml'];body=x.replace('sont soumis à une taxe fixe de publicité foncière ou, le cas échéant, à un droit fixe d\'enregistrement de 25 €','sont exonérés de la taxe fixe de publicité foncière ou, le cas échéant, du droit fixe d\'enregistrement de 25 €').replace('Le tarif mentionné au premier alinéa s\'applique également','L’exonération mentionnée au premier alinéa s’applique également')
put('846 bis',body+paras(T,AUT), 'Supprime le fixe25€ des procurations, mainlevées, actes de notoriété hors usucapion et déclarations d’insaisissabilité visées.', 'Les deux alinéas et l’exception concernant la notoriété constatant l’usucapion restent complets. La référence auxL526-1à3 du commerce définit des actes ; elle ne supprime ni l’insaisissabilité ni la publicité. Les émoluments distincts ne sont pas une taxe supprimée.',fam,'tax_removed','25€ sur les actes listés et déclarations/états L526-1à3 ; usucapion exclue de ce fixe.','Même champ exonéré du25€, sans changer le régime des actes constatant l’usucapion.','un droit fixe d\'enregistrement de 25 €',"du droit fixe d'enregistrement de 25 €", 'Les protections civiles et l’insaisissabilité sous-jacentes restent. L’usucapion n’est pas soumise à un nouveau taux ; la suppression du droit propre aux mainlevées est distincte de la suppression de la CSI et ne compte pas deux fois cette dernière.')
# Conservation des champs et du taux proportionnel1020 ; retrait du fixe et coordination1053 déjà exonéré.
x=by['1020']['source_xml'];body=x.replace('1031,1053,1054','1031,1054');body=body.replace('Dans le cas contraire, et sauf exonération, ces dispositions sont soumises à une imposition fixe de 25 €. Celle-ci s\'applique, dans tous les cas, aux dispositions sujettes à publicité foncière des actes relatifs aux transmissions de biens visés à l\'article 1039.',"Dans le cas contraire, ces dispositions sont exonérées de l’imposition fixe de 25 €. Les dispositions sujettes à publicité foncière des actes relatifs aux transmissions de biens visés à l’article 1039 sont également exonérées de cette imposition fixe, sans être soumises, du seul fait de cette suppression, à l’imposition proportionnelle du présent article.")
put('1020',body+paras('Les exonérations plus favorables prévues notamment à l’article 1053 demeurent applicables. Les transmissions résultant de décès exonérés par l’article 750 ter ne peuvent devenir imposables par la seule application du présent article.',T,AUT), 'Supprime seulement le fixe25€ résiduel, conserve le0,70% autonome et coordonne l’exonération plus favorable déjà proposée1053.', 'Tous les articles de la liste,1039 et677 officiels/proposés ont été lus ; liste conservée sauf1053 déjà expressément exonéré dans sa proposition actuelle. Ne pas transformer la suppression du fixe en extension du0,70%, notamment pour1039. Le0,70% n’est pas la CSI0,10% ; son maintien dans son champ est explicite. Les exceptions de1133quater et la suppression des successions restent.',fam,'tax_removed','0,70% dans le champ6771°à4° ; sinon fixe25€, et toujours25€ pour1039.','0,70% inchangé dans son champ restant ; fixe25€ supprimé et1039 non basculé au proportionnel.','ces dispositions sont soumises à une imposition fixe de 25 €','ces dispositions sont exonérées de l’imposition fixe de 25 €.', 'Toutes les exonérations sectorielles continuent de produire effet. L’exonération élargie1053 déjà proposée est respectée, celle de1039 n’est pas rendue moins favorable, et la réserve d’absence de taxation des décès nouveaux évite une résurrection indirecte des droits successoraux.')
x=by['1048 ter']['source_xml'];body=x.replace("Sont soumis à la perception de l'imposition mentionnée à l'article 680 :","Sont exonérés de l’imposition fixe mentionnée à l’article 680 :")
put('1048 ter',body+paras(T,'Cette exonération ne modifie ni la validité, ni la durée, ni les garanties, ni les conditions de retrait des autorisations, baux et conventions visés aux 1° à 6°. Les redevances domaniales, loyers et autres impositions ayant un fait générateur distinct conservent leur régime ; aucune perception ne remplace le droit fixe supprimé.',AUT), 'Coordonne le retrait du fixe680 pour les six catégories de conventions et autorisations domaniales, sans modifier leur droit public.', 'Les1°à6° et toutes leurs références sont conservés mot pour mot ; aucun texte CGPPP/CGCT/CSP extérieur au corpus n’est prétendu réécrit. L’autorisation domaniale et les redevances ne disparaissent pas par la suppression d’une imposition fixe. Il n’est pas ajouté d’agrément fiscal.',fam,'coordination','Ces actes sont explicitement renvoyés au droit fixe680.','Même liste exonérée du fixe680 ; pas de modification des conditions domaniales ou contractuelles.','Sont soumis à la perception de l\'imposition mentionnée à l\'article 680','Sont exonérés de l’imposition fixe mentionnée à l’article 680', 'Le renvoi spécial n’introduit pas un nouveau tarif une fois680 supprimé. Les avantages des baux et conventions, exonérations domaniales et garanties des parties sont préservés ; l’existence de redevances distinctes ne permet pas de les compter comme un impôt supprimé.',classification='coordination_only')
x=by['1051']['source_xml'];body=x.replace('Sont soumis à une imposition fixe de 125 €','Sont exonérés de l’imposition fixe de 125 €')
put('1051',body+paras(T,'Les catégories d’organismes et d’opérations, les dates de leurs dispositifs et les exonérations plus favorables demeurent inchangées. La suppression de l’imposition fixe ne peut, par elle-même, soumettre ces opérations à un droit proportionnel. Pour les opérations auxquelles le 4°, dans sa rédaction antérieure à l’article 30 de la loi n° 2018-1317 du 28 décembre 2018, demeure applicable en vertu du V, E de cet article, la suppression du seul droit fixe s’applique également dans les conditions temporelles du présent article. Leurs autres exonérations et avantages transitoires demeurent inchangés.',AUT), 'Supprime les125€ sur les opérations de logement social précisément énumérées, conserve les catégories et transitions.', 'Les1°,1°bis,2°,3°et4°abrogé sont conservés sans réouverture de l’acquisition temporaire d’avant31décembre2013. La note2018 maintient certains anciens4° ultramarins : elle est expressément préservée, pas réputée entièrement abrogée. Les référencesHLM/agrémentsL365-2/différents bailleurs et logements intermédiaires restent ; elles ne sont pas remplacées par un champ plus étroit.',fam,'tax_removed','125€ sur transferts et attributions énumérés, avec composantes historiques propres.','Même champ et mêmes dates, sans fixe125€ pour les nouveaux faits générateurs ; anciens avantages et4°transitoire préservés.','Sont soumis à une imposition fixe de 125 €','Sont exonérés de l’imposition fixe de 125 €', 'Les catégories favorables de transferts sociaux ne basculent pas vers un tarif ordinaire ; les1°et3° couvrent toujours leurs divers organismes, le1°bis garde sa date historique et la note2018 protège les droits antérieurs ultramarins. Les autres exonérations et aides ne sont pas supprimées.')
# CSI : un seul fait générateur et une seule mesure, ses exécutions ne sont pas autant de taxes.
cid='contribution-securite-immobiliere-suppression'
put('879',paras('I. – La contribution de sécurité immobilière est supprimée pour toutes les réquisitions et demandes présentées à compter de l’entrée en vigueur de la loi portant cette suppression. Cette suppression s’applique aux publications, inscriptions, mentions, radiations, renseignements, copies et relevés pour lesquels cette contribution était exigible, quel que soit leur mode de traitement, y compris lorsque l’acte, le droit ou l’inscription concerné est antérieur. Aucun versement, avance, minimum, complément ou garantie de cette seule contribution n’est exigible pour ces demandes, et leur dépôt ou leur traitement ne peut être refusé ou suspendu au seul motif de son absence de paiement.', 'II. – Pour les réquisitions et demandes présentées avant cette date, les dispositions applicables à leur date continuent de régir la liquidation, le recouvrement, les avances, les exonérations, réductions, imputations, restitutions, contrôles, prescriptions et recours. Les exonérations de l’État et celles expressément prévues par la loi restent applicables dans leur champ. La suppression ne crée aucun droit général au remboursement des contributions antérieurement dues ; les sommes versées sans être dues demeurent restituables selon les voies applicables, avec une seule imputation ou restitution de chaque versement.', 'III. – Les formalités civiles, la publicité foncière et l’enregistrement demeurant légalement requis, leurs délais, leur rang, leur opposabilité et les droits des tiers ne sont pas supprimés. Les conditions légales de communication des documents, la protection des données et des secrets restent applicables. Aucun impôt, droit, redevance, salaire ou émolument de remplacement de la contribution supprimée n’est institué. Les autres taxes et les rémunérations ou émoluments distincts légalement dus conservent leur régime propre et leurs exonérations.'), 'Supprime prospectivement la CSI entière, y compris tarifs fixes/proportionnels, avances et refus attachés à ce seul paiement.', 'Fait générateur de transition explicite : présentation de la réquisition ou demande, pas date de l’acte sous-jacent. La suppression vaut aussi pour renseignements/copies de formalités anciennes et radiations futures d’inscriptions anciennes. La publicité et ses rangs restent ; la CSI n’est ni la TPF/DMTO, ni les émoluments du notaire. Coût public du service et perte brute/net consolidé non chiffrés. Les17articles d’exécution se dédupliquent sous ce même identifiant. Le champ fusionné de l’ancienne propositionAnnIII253 est inclus, pas une seconde abolition indépendante.',cid,'tax_removed','CSI due aux demandes de formalités8781°/2° ; taux0,05%/0,10% et tarifs fixes/minima selon881BàM, avantages propres881L/O.','Aucune CSI sur réquisitions/demandes futures, sans paiement ou garantie de substitution ; formalités et impôts distincts restent.','Une contribution de sécurité immobilière est due à l’Etat'.replace('’',"'"),'La contribution de sécurité immobilière est supprimée', 'Les exonérations expresses, tarifs réduits, demi-tarifHLM, minima et règles de remboursement des anciennes demandes restent dans leur champ historique. Pour les nouvelles demandes, toute la contribution disparaît sans prélèvement équivalent ; aucun bénéficiaire auparavant exonéré n’est désormais taxé. Publicité, rang et droits des tiers ne sont pas amputés.')
# CGI878 : compétences civiles intactes, seule collecte résiduelle deCSI.
x=by['878']['source_xml'];body=x.replace("De la perception des taxes et de la contribution prévue à l'article 879 exigibles à l'occasion des formalités prévues aux 1° et 2°.","De la perception des taxes exigibles à l'occasion des formalités prévues aux 1° et 2° et, pour les seules réquisitions ou demandes antérieures à la suppression prévue à l'article 879, de la contribution de sécurité immobilière et de ses régularisations restant légalement dues.")
put('878',body, 'Conserve les missions du service et limite la perception deCSI aux créances anciennes.', 'Les1°/2° civils/fusionnés restent exacts ; seul3° coordonné. Ni DMTO ni TPF ni fichier immobilier ne sont supprimés. La nouvelle loi ne transforme pas le service en financeur gratuitement réputé couvert : fonctionnement à financer sans recette inventée.',cid,'coordination','Le service perçoit les taxes etCSI à l’occasion de ses formalités.','Taxes distinctes maintenues ; CSI uniquement ancienne et régularisations.','De la perception des taxes et de la contribution prévue à l\'article 879','pour les seules réquisitions ou demandes antérieures à la suppression prévue à l\'article 879', 'Les avantages relatifs aux taxes distinctes sont inchangés. Le service garde ses missions protectrices et ses compétences territoriales ; les anciennes exonérationsCSI ne sont pas transformées en créances exigibles par ce renvoi.',classification='coordination_only')
put('880',paras('Les dispositions du présent article s’appliquent exclusivement aux réquisitions ou demandes antérieures à l’entrée en vigueur de la suppression prévue à l’article 879.' )+by['880']['source_xml']+paras('Aucune avance de contribution de sécurité immobilière ni quittance de cette seule contribution n’est exigée pour les réquisitions et demandes nouvelles. Les règles de quittance ou d’avance nécessaires à un autre droit légalement dû ne sont pas supprimées.',CSI), 'Retire l’avance et la quittance exclusivementCSI des nouvelles demandes ; conserve les justificatifs de paiement anciens.', 'Les deux alinéas sources sont conservés en entier pour les anciennes demandes. Pas de nouvelle quittance à zéro ou d’attestation de remplacement ; les versements deCSI ne sont imputés ou remboursés qu’une seule fois suivant879II.',cid,'coordination','CSI payée d’avance et quittance détaillée.','Aucune avance ni quittance propreCSI pour les nouvelles demandes ; anciennes règles conservées.','La contribution de sécurité immobilière est payée d’avance'.replace('’',"'"),'Aucune avance de contribution de sécurité immobilière ni quittance de cette seule contribution n’est exigée', 'Les paiements et preuves des anciens dossiers restent opposables ; les indus restent restituables sans remboursement général d’un impôt antérieurement dû. Les exonérations n’exigent pas une quittance fictive.',classification='coordination_only')
x=by['881']['source_xml'];body=x.replace("I. – La contribution dont ont été exonérées les inscriptions de privilège ou d'hypothèque requises par l'Etat est due lors de leur radiation.","I. – La contribution dont ont été exonérées les inscriptions de privilège ou d'hypothèque requises par l'Etat n'est due lors de leur radiation que si la demande de radiation a été présentée avant l'entrée en vigueur de la suppression prévue à l'article 879. Une demande de radiation postérieure n'ouvre pas droit à contribution, même si l'inscription est antérieure.")
