for n in ['881 B','881 C','881 D','881 E','881 F','881 G','881 H','881 I','881 J','881 K','881 M']:
 src=plain(by[n]['source_xml']);body=paras('Le présent article est abrogé pour les réquisitions et demandes auxquelles s’applique la suppression prévue à l’article 879. Aucun tarif, minimum ou complément prévu au présent article n’est perçu pour ces réquisitions et demandes.',CSI,'Les dispositions antérieures du présent article restent applicables aux réquisitions et demandes antérieures, avec leurs assiettes, plafonds, réductions, exonérations et voies de restitution. Les formalités civiles, les communications légalement autorisées et les droits des tiers demeurent applicables ; aucune valeur n’est à déclarer au seul titre de la contribution supprimée, sans préjudice des déclarations encore nécessaires à un autre impôt ou à une formalité civile.')
 facts={'881 B':'8€ pour bordereaux rectificatifs ou complémentaires ; dépôt civil maintenu.','881 C':'15€ pour17catégories énumérées ; aucune des formalités de saisie, mentions, états descriptifs, conventions ou avenants n’est abolie.','881 D':'12€ par personne/immeuble, supplément5€ au-delà troisième personne et2€ au-delà cinquièmeimmeuble ; demande et limites de communication restent.','881 E':'Copies6€/30€/15€ et acompte15€ non remboursable pour recherches sans références ; tous supprimés seulement pour nouvelles demandes.','881 F':'5€ par personne pour relevés des archives hypothécaires ; archives conservées.','881 G':'Renvoi tarifaire881D/E pour copies/renseignements des arrêtés2008/1979, exception881F ; communications restent.','881 H':'0,05% sur créance garantie, évaluation des créances indéterminées pourCSI ; le bordereau civil reste.','881 I':'0,05% sur subrogation/cession d’antériorité et convention de rechargement2416 ; rang et garanties non supprimés.','881 J':'0,10% radiation et0,05% radiation2436, plafonds favorables de réduction du gage et de divisions conservés pour anciennes demandes.','881 K':'0,10% publication, valeur et refus attachés àCSI ; autres assiettes fiscales/civiles restent nécessaires.','881 M':'Minima8€ inscription/rechargement et15€ radiation/publication, y compris publications non proportionnelles ; ne pas confondre avec le minimum général674 de25€.'}[n]
 put(n,body,'Coordonne la suppression entière deCSI en retirant prospectivement ce seul tarif d’exécution.',facts+' Tout le texte et toutes les notes de la source sont lus. Aucun nouveau tarif, date de promulgation, compensation ni économie nationale n’est inventé.',cid,'coordination',facts,'Tarif, minima et compléments deCSI supprimés pour nouvelles demandes ; régime ancien conservé.',src[:min(110,len(src))],'Aucun tarif, minimum ou complément prévu au présent article n’est perçu', 'Les exonérations, bases plafonnées et taux réduits de la source demeurent utilisables pour les anciennes demandes. Pour les nouvelles, la suppression de touteCSI rend ces tarifs sans objet sans les remplacer ; les droits civils et les autres avantages fiscaux distincts restent.',classification='coordination_only',meta={'change_type':'full_repeal','repeal_policy_id':'editorial_direction_2026_10_19','repeal_scope':'Suppression prospective du seul tarif et des modalités de contribution de sécurité immobilière de l’article'+n+'pour nouvelles réquisitions et demandes, anciens droits et protections civiles préservés.'})
put('881 N',paras('Les dispositions des articles 879 à 881 M, notamment la suppression de la contribution de sécurité immobilière pour les nouvelles réquisitions et demandes ainsi que le maintien du régime applicable aux réquisitions et demandes antérieures, sont applicables aux formalités intéressant les immeubles situés à Saint-Barthélemy, à Saint-Martin et à Saint-Pierre-et-Miquelon.'), 'Maintient le champ territorial des trois collectivités, y compris pour la suppression et le stock ancien.', 'Aucun nouveau régime fiscal local n’est inventé. Les trois territoires du texte source restent exactement ceux du dispositif ; Mayotte relève de son avantage propre881O et de la suppression générale879. L’extension géographique de la source n’est pas une taxe nouvelle.',cid,'coordination','Les articles879à881M s’appliquent aux immeubles des troiscollectivités.','Même champ, explicitement pour l’abolition prospective et les créances anciennes.','Saint-Barthélemy, à Saint-Martin et à Saint-Pierre-et-Miquelon','Saint-Barthélemy, à Saint-Martin et à Saint-Pierre-et-Miquelon', 'Les contribuables de ces territoires bénéficient de la suppression sans reprise de leurs exonérations ou tarifs anciens plus favorables. Aucun prélèvement local substitutif et aucune restriction de la publicité ne sont créés.',classification='coordination_only')
